import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, Color } = ctx.THREE;

  // Root container
  const root = new Group();
  root.position.set(
    config.position?.[0] ?? 1.25,
    config.position?.[1] ?? -0.19999999999999996,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // Geometry
  const geometry = new PlaneGeometry(1, 1, 64, 64); // size will be controlled by parent scaling

  // Material
  const material = new MeshStandardNodeMaterial({
    color: new Color(config.visualSpec?.colors?.paper ?? '#e8ecf2'),
    side: DoubleSide,
    metalness: 0,
    roughness: 0.6,
    transparent: false,
  });

  // Mesh
  const plane = new Mesh(geometry, material);
  plane.name = config.name ?? 'parallax-plane';
  root.add(plane);

  // Load textures asynchronously (synchronous function contract)
  const imageUrl = config.imageUrl || config.assets?.imageUrl;
  const depthUrl = config.depthMapUrl || config.assets?.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  if (depthUrl) {
    ctx.textureLoader
      .loadTexture(depthUrl)
      .then((tex) => {
        material.displacementMap = tex;
        material.displacementScale = 0.15; // subtle depth
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  // Apply cinematic primitives
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      try {
        const handle = ctx.primitives[prim.name](root, prim.params ?? {});
        primitiveHandles.push(handle);
      } catch (e) {
        // ignore missing primitive
      }
    }
  }

  // Interaction handlers
  const handlers = {};

  // Hover rise‑in effect
  let hoverTimeline = null;
  handlers.hover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline({ defaults: { ease: 'power3.out' } });
    hoverTimeline.to(
      root.position,
      {
        y: (config.position?.[1] ?? -0.19999999999999996) + 0.15,
        duration: 0.7,
      },
      0
    );
  };

  // Click emit
  handlers.click = () => {
    ctx.emit('hub-pricing.select', {});
  };

  root.userData.handlers = handlers;

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose geometry
    geometry.dispose();

    // Dispose material and its textures
    if (material.map) material.map.dispose();
    if (material.displacementMap) material.displacementMap.dispose();
    material.dispose();

    // Kill GSAP timeline
    if (hoverTimeline) hoverTimeline.kill();

    // Cleanup primitives
    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') {
        handle.cleanup();
      }
    }
  };

  return root;
}
